    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = DateTime.UtcNow });
    }
}

// Cosmos DB context with fixes for EF Core 9 breaking changes
class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");

        // Breaking Change #1: Synchronous I/O is no longer supported on Cosmos.
        // EF Core 9 throws InvalidOperationException for sync queries like .ToList().
        // Fix: Enable sync I/O via CosmosOptionsExtension if migration is incremental,
        // but prefer converting to async (see MigrationRunner.cs).
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking Change #2: Cosmos discriminator property is now "$type" by default.
        // Existing documents use "Discriminator". Must explicitly configure to keep
        // reading existing data.
        modelBuilder.Entity<Document>().HasDiscriminator<string>("Discriminator");
    }
}

class Document
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

