class MigrationRunner
{
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            using var transaction = db.Database.BeginTransaction();
            db.Database.Migrate();
            transaction.Commit();
        });
    }

    // Breaking Change #3: EF Core 9 Cosmos provider no longer supports synchronous
    // I/O (ToList, First, Single, etc.). Must use async equivalents.
    async Task QueryCosmosAsync(CosmosDbContext cosmosDb)
    {
        // BEFORE (throws InvalidOperationException in EF Core 9):
        //   var docs = cosmosDb.Documents.ToList();
        //   var first = cosmosDb.Documents.First();

        // AFTER: use async methods
        var docs = await cosmosDb.Documents.ToListAsync();
        var first = await cosmosDb.Documents.FirstAsync();
    }
}

